using FamilyVeda.Application.Common;
using FamilyVeda.Domain.Common;
using FamilyVeda.Domain.Records;

namespace FamilyVeda.Application.Records;

public sealed record HealthRecordDto(Guid Id, Guid MemberId, RecordType RecordType, string Title, string? Summary, DateOnly OccurredOn, bool SharedWithFamilyHead = false);
public sealed record UpsertHealthRecordRequest(RecordType RecordType, string Title, string? Summary, DateOnly OccurredOn);
public sealed record VitalDto(Guid Id, Guid MemberId, string VitalType, decimal Value, string Unit, DateTimeOffset MeasuredAt);
public sealed record CreateVitalRequest(string VitalType, decimal Value, string Unit, DateTimeOffset MeasuredAt);
public sealed record VitalTrendDto(string VitalType, IReadOnlyList<VitalPointDto> Points);
public sealed record VitalPointDto(DateTimeOffset MeasuredAt, decimal Value, string Unit);
public sealed record LabReportDto(Guid Id, Guid MemberId, string OriginalFileName, OcrStatus OcrStatus, DateTimeOffset? CollectedAt,
    bool SharedWithFamilyHead = false, bool HasOriginalFile = false, LabRangeSummaryDto? RangeSummary = null, string? OcrErrorCode = null);
/// <summary>A report in "Recently deleted". Permanent deletion is refused while confirmed values may have informed a triage case.</summary>
public sealed record DeletedLabReportDto(Guid Id, Guid MemberId, string OriginalFileName, string ContentType, OcrStatus OcrStatus,
    DateTimeOffset? CollectedAt, DateTimeOffset DeletedAt, bool CanDeletePermanently);
/// <summary>Original image bytes and their safe display content type. Storage paths are never exposed.</summary>
public sealed record LabReportFileDto(byte[] Content, string ContentType);
/// <summary>Counts only — range position against the printed reference, never an interpretation (RULE 1).</summary>
public sealed record LabRangeSummaryDto(int BelowRange, int WithinRange, int AboveRange, int RangeUnavailable);
/// <summary>Owner-only toggle: keep an adult's item private from the Family Head (default) or share it.</summary>
public sealed record UpdateSharingRequest(bool SharedWithFamilyHead);
public sealed record LabValueDto(Guid Id, string Analyte, decimal Value, string Unit, decimal? ReferenceLow, decimal? ReferenceHigh, bool WasManuallyConfirmed, LabRangeStatus RangeStatus);
public sealed record LabReportDetailDto(Guid Id, Guid MemberId, string OriginalFileName, OcrStatus OcrStatus, DateTimeOffset? CollectedAt, IReadOnlyList<LabValueDto> Values, IReadOnlyList<HereditaryFlagDto> Flags, bool SharedWithFamilyHead = false, string? OcrErrorCode = null);
public sealed record ConfirmLabValueRequest(Guid Id, string Analyte, decimal Value, string Unit, decimal? ReferenceLow, decimal? ReferenceHigh);
public sealed record ConfirmLabReportRequest(IReadOnlyList<ConfirmLabValueRequest> Values, IReadOnlyList<Guid> ConfirmedFlagIds);
public sealed record LabExtractionResultDto(Guid ReportId, OcrStatus Status, int ValuesExtracted, int FlagsExtracted, bool RequiresManualReview);
public sealed record ExtractedLabValue(string Analyte, decimal Value, string Unit, decimal? ReferenceLow, decimal? ReferenceHigh);
public sealed record ExtractedHereditaryFlag(string ConditionCode, string Finding, decimal Confidence);
public sealed record LabExtractionPayload(IReadOnlyList<ExtractedLabValue> Values, IReadOnlyList<ExtractedHereditaryFlag> Flags);
public sealed record HereditaryFlagDto(Guid Id, Guid MemberId, string ConditionCode, string Finding, decimal Confidence, bool ManuallyConfirmed);

public interface IRecordService
{
    Task<PagedResult<HealthRecordDto>> GetRecordsAsync(Guid memberId, int page, int pageSize, string? search, RecordType? type, string sort, CancellationToken cancellationToken);
    Task<HealthRecordDto> CreateRecordAsync(Guid memberId, UpsertHealthRecordRequest request, CancellationToken cancellationToken);
    Task<HealthRecordDto> UpdateRecordAsync(Guid recordId, UpsertHealthRecordRequest request, CancellationToken cancellationToken);
    Task DeleteRecordAsync(Guid recordId, CancellationToken cancellationToken);
    Task<IReadOnlyList<VitalDto>> GetVitalsAsync(Guid memberId, CancellationToken cancellationToken);
    Task<VitalDto> AddVitalAsync(Guid memberId, CreateVitalRequest request, CancellationToken cancellationToken);
    Task<IReadOnlyList<VitalTrendDto>> GetVitalTrendsAsync(Guid memberId, CancellationToken cancellationToken);
    Task<IReadOnlyList<LabReportDto>> GetLabReportsAsync(Guid memberId, CancellationToken cancellationToken);
    Task<LabReportDto> GetLabReportAsync(Guid reportId, CancellationToken cancellationToken);
    Task<LabReportFileDto> GetLabReportFileAsync(Guid reportId, CancellationToken cancellationToken);
    Task<LabReportDto> UploadLabReportAsync(Guid memberId, string originalFileName, string contentType, long sizeBytes, Stream content, DateTimeOffset? collectedAt, CancellationToken cancellationToken);
    Task<LabReportDetailDto> GetLabReportDetailAsync(Guid reportId, CancellationToken cancellationToken);
    Task<LabReportDetailDto> ConfirmLabReportAsync(Guid reportId, ConfirmLabReportRequest request, CancellationToken cancellationToken);
    Task<IReadOnlyList<HereditaryFlagDto>> GetHereditaryFlagsAsync(Guid memberId, CancellationToken cancellationToken);
    Task<HealthRecordDto> SetRecordSharingAsync(Guid recordId, bool sharedWithFamilyHead, CancellationToken cancellationToken);
    Task DeleteLabReportAsync(Guid reportId, CancellationToken cancellationToken);
    Task<IReadOnlyList<DeletedLabReportDto>> GetDeletedLabReportsAsync(Guid memberId, CancellationToken cancellationToken);
    Task<LabReportDto> RestoreLabReportAsync(Guid reportId, CancellationToken cancellationToken);
    Task PermanentlyDeleteLabReportAsync(Guid reportId, CancellationToken cancellationToken);
    Task<LabReportDto> SetLabReportSharingAsync(Guid reportId, bool sharedWithFamilyHead, CancellationToken cancellationToken);
}

public interface ILabExtractionService
{
    /// <summary>Checks access, marks the report Processing and queues the read. Returns at once; the read runs in the background.</summary>
    Task<LabExtractionResultDto> ExtractAsync(Guid reportId, CancellationToken cancellationToken);
    /// <summary>Runs one queued read (called only by the background worker, never by a client).</summary>
    Task RunQueuedAsync(Guid reportId, CancellationToken stoppingToken);
}

/// <summary>In-process queue of lab reports waiting to be read. Singleton; drained by LabExtractionWorker.</summary>
public interface ILabExtractionQueue
{
    ValueTask QueueAsync(Guid reportId, CancellationToken cancellationToken);
    ValueTask<Guid> DequeueAsync(CancellationToken cancellationToken);
}

public interface IOcrService
{
    Task<string> ExtractTextAsync(string filePath, CancellationToken cancellationToken);
}

/// <summary>Why reading a lab report failed. Stored on the report and mapped to patient-facing copy by each client.</summary>
public static class OcrFailureCodes
{
    public const string TooManyPages = "REPORT_TOO_MANY_PAGES";
    public const string TooMuchText = "REPORT_TOO_MUCH_TEXT";
    public const string NoValuesFound = "NO_VALUES_FOUND";
    public const string Unreadable = "OCR_UNREADABLE";
    public const string TimedOut = "OCR_TIMEOUT";
    public const string PdfUnsupported = "PDF_UNSUPPORTED";
    public const string EngineUnavailable = "OCR_ENGINE_UNAVAILABLE";
    public const string Interrupted = "OCR_INTERRUPTED";
    public const string Cancelled = "OCR_CANCELLED";
    public const string Failed = "OCR_FAILED";

    /// <summary>A read still "processing" after this long was cut off (restart, crash) and may be retried.
    /// Reads are queued and run one at a time, so this covers a full batch (~15 reports x the read budget);
    /// restarts are recovered at startup by LabExtractionWorker, so this is only the last-resort window.</summary>
    public static readonly TimeSpan StaleProcessingAfter = TimeSpan.FromMinutes(45);
}
